scwin.form_onLoadCompleted = function(obj) {
    var jsonData = [{
        "oparam1": "A70012760000000",
        "oparam2": "100000000386728",
        "oparam3": "1",
        "oparam4": "",
        "oparam5": "201608010000001",
        "rowStatus": "R"
    }];
    dst_OutPut.setJSON(jsonData);
};
scwin.tab_bldInfo_onchange = function(tabID, idx, userTabID) {
    if (idx == 1) {
        //debugger;
        dst_ngmsadd30030t04_out_01_dong.removeAll();
        for (var i = 0; i < dst_OutPut.getRowCount(); i++) {
            dst_ngmsadd30030t04_out_01_dong.insertRow();
            dst_ngmsadd30030t04_out_01_dong.setCellData(i, "chk_col", "0");
            dst_ngmsadd30030t04_out_01_dong.setCellData(i, "bld_cd", dst_OutPut.getCellData(i, "oparam1"));
            dst_ngmsadd30030t04_out_01_dong.setCellData(i, "bldblk_num", dst_OutPut.getCellData(i, "oparam2"));
            dst_ngmsadd30030t04_out_01_dong.setCellData(i, "bldblk_nm", dst_OutPut.getCellData(i, "oparam3"));
            dst_ngmsadd30030t04_out_01_dong.setCellData(i, "syn_bldblk_nm", dst_OutPut.getCellData(i, "oparam4"));
            dst_ngmsadd30030t04_out_01_dong.setCellData(i, "bldblk_rcv_num", dst_OutPut.getCellData(i, "oparam5"));
        }
        //debugger;	
        grd_dong.setFocusedCell(0, 1, false);
        var pos = dst_ngmsadd30030t04_out_01_dong.getRowPosition();
        //ngmf.trace("dst_ngmsadd30030t04_out_01_dong==> "+dst_ngmsadd30030t04_out_01_dong.getRowPosition());
        console.log("dst_ngmsadd30030t04_out_01_dong==> " + dst_ngmsadd30030t04_out_01_dong.getRowPosition());
    }
};
scwin.trigger2_onclick = function(e) {
    //debugger;
    dst_ngmsadd30030t04_out_01_dong.removeAll();
    for (var i = 0; i < dst_OutPut.getRowCount(); i++) {
        dst_ngmsadd30030t04_out_01_dong.insertRow();
        dst_ngmsadd30030t04_out_01_dong.setCellData(i, "chk_col", "0");
        dst_ngmsadd30030t04_out_01_dong.setCellData(i, "bld_cd", dst_OutPut.getCellData(i, "oparam1"));
        dst_ngmsadd30030t04_out_01_dong.setCellData(i, "bldblk_num", dst_OutPut.getCellData(i, "oparam2"));
        dst_ngmsadd30030t04_out_01_dong.setCellData(i, "bldblk_nm", dst_OutPut.getCellData(i, "oparam3"));
        dst_ngmsadd30030t04_out_01_dong.setCellData(i, "syn_bldblk_nm", dst_OutPut.getCellData(i, "oparam4"));
        dst_ngmsadd30030t04_out_01_dong.setCellData(i, "bldblk_rcv_num", dst_OutPut.getCellData(i, "oparam5"));
    }
    //debugger;	
    grd_dong.setFocusedCell(0, 1, false);
    //ngmf.trace("dst_ngmsadd30030t04_out_01_dong==> "+dst_ngmsadd30030t04_out_01_dong.getRowPosition());	
    var pos = dst_ngmsadd30030t04_out_01_dong.getRowPosition();
    console.log("dst_ngmsadd30030t04_out_01_dong==> " + dst_ngmsadd30030t04_out_01_dong.getRowPosition());
    logStep3 = "dst_ngmsadd30030t04_out_01_dong==> " + pos;
};
scwin.tabClick = function(tabID, idx) {
    if (idx == 1) {
        dst_ngmsadd30030t04_out_01_dong.removeAll();
        //debugger;
        for (var i = 0; i < dst_OutPut.getRowCount(); i++) {
            dst_ngmsadd30030t04_out_01_dong.insertRow();
            dst_ngmsadd30030t04_out_01_dong.setCellData(i, "chk_col", "0");
            dst_ngmsadd30030t04_out_01_dong.setCellData(i, "bld_cd", dst_OutPut.getCellData(i, "oparam1"));
            dst_ngmsadd30030t04_out_01_dong.setCellData(i, "bldblk_num", dst_OutPut.getCellData(i, "oparam2"));
            dst_ngmsadd30030t04_out_01_dong.setCellData(i, "bldblk_nm", dst_OutPut.getCellData(i, "oparam3"));
            dst_ngmsadd30030t04_out_01_dong.setCellData(i, "syn_bldblk_nm", dst_OutPut.getCellData(i, "oparam4"));
            dst_ngmsadd30030t04_out_01_dong.setCellData(i, "bldblk_rcv_num", dst_OutPut.getCellData(i, "oparam5"));
        }
        //debugger;	
        grd_dong.setFocusedCell(0, 1, false);
        var pos = dst_ngmsadd30030t04_out_01_dong.getRowPosition();
        //ngmf.trace("dst_ngmsadd30030t04_out_01_dong==> "+dst_ngmsadd30030t04_out_01_dong.getRowPosition());
        console.log("dst_ngmsadd30030t04_out_01_dong==> " + dst_ngmsadd30030t04_out_01_dong.getRowPosition());
        logStep2_5 = "dst_ngmsadd30030t04_out_01_dong==> " + pos;
    }
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 개발자모드(F12)를 실행한다.
    //1. Execute the developer mode (F12) after executing the sample file.
    //Verify step 1. 샘플화면이 실행되고 개발자모드가 실행된다.
    //1. The sample screen is executed and the developer mode is executed.
    //Test step 2. 실행화면에서 건물동/호수정보탭을 클릭한다.
    //2. On the Run screen, click the Buildings / Lakes Information tab.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tab_bldInfo_tab_tabpg02').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 2. console창에 값이 보여진다.dst_ngmsadd30030t04_out_01_dong==> 0
    //2. The value is displayed in the console window. Dst_ngmsadd30030t04_out_01_dong ==> 0
    WebSquare.wUnit.addCommand("assert", "logStep2_5 == 'dst_ngmsadd30030t04_out_01_dong==> 0'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 이벤트버튼을 클릭한다.
    //3. Click the Events button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 3. console창에 값이 보여진다.dst_ngmsadd30030t04_out_01_dong==> 0
    //3. The value is displayed in the console window. Dst_ngmsadd30030t04_out_01_dong ==> 0
    WebSquare.wUnit.addCommand("assert", "logStep3 == 'dst_ngmsadd30030t04_out_01_dong==> 0'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. 건물정보탭을 클릭한다.
    //4. Click the Building Information tab.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tab_bldInfo_tab_tabpg01').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 4. 건물정보탭으로 전환된다.
    //4. Switch to the Building Information tab.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#tab_bldInfo_tab_tabpg01').hasClass('w2tabcontrol_selected')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 5. 건물동/호수정보탭을 클릭한다.
    //5. Click the Buildings / Lakes Information tab.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tab_bldInfo_tab_tabpg02').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 5. console창에 값이 보여진다.dst_ngmsadd30030t04_out_01_dong==> 0(이전에는 console값이 0이아닌 null로보여짐)
    //5. The value is displayed in the console window. Dst_ngmsadd30030t04_out_01_dong ==> 0 (Previously console value is shown as null instead of 0)
    WebSquare.wUnit.addCommand("assert", "logStep2_5 == 'dst_ngmsadd30030t04_out_01_dong==> 0'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.logStep2_5 = "";
    window.logStep3 = "";
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 27-Feb-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
